def encode_amount(dollars: str) -> str:
    if '.' not in dollars:
        dollars = dollars + '.00'
    int_part, frac_part = dollars.split('.', 1)
    if len(frac_part) == 1:
        frac_part = frac_part + '0'
    elif len(frac_part) > 2:
        frac_part = frac_part[:2]
    negative = int_part.startswith('-')
    if negative:
        int_part = int_part[1:]
    int_part = int_part or '0'
    int_part = int_part.lstrip('0') or '0'
    frac_part = frac_part.ljust(2, '0')[:2]
    if negative:
        return f'-{int_part}.{frac_part}'
    return f'{int_part}.{frac_part}'

