import ledger


def transfer(acct, cents, reason):
    return ledger.post(acct, cents, memo=reason)

def encode_amount(dollars: str) -> str:
    # Parse the input string
    s = dollars.strip()
    if s.startswith('-'):
        sign = '-'
        num_str = s[1:]
    else:
        sign = '+'
        if s.startswith('+'):
            num_str = s[1:]
        else:
            num_str = s

    # Split integer and fractional parts
    if '.' in num_str:
        int_part, frac_part = num_str.split('.', 1)
    else:
        int_part = num_str
        frac_part = ''

    # Pad or truncate fractional part to exactly 2 digits
    if len(frac_part) < 2:
        frac_part = frac_part.ljust(2, '0')
    elif len(frac_part) > 2:
        frac_part = frac_part[:2]

    # Remove leading zeros from integer part, but keep at least one digit
    int_part = int_part.lstrip('0')
    if int_part == '':
        int_part = '0'

    # Combine to get total cents (minor units)
    cents_str = int_part + frac_part

    # Compute check digit: sum of digits mod 10
    digit_sum = sum(int(ch) for ch in cents_str)
    check = str(digit_sum % 10)

    return f"{sign}{cents_str}#{check}"

