def encode_amount(dollars: str) -> str:
    # Determine sign
    if dollars.startswith('-'):
        sign = '-'
        num_str = dollars[1:]
    else:
        sign = '+'
        num_str = dollars

    # Split into dollars and cents parts
    if '.' in num_str:
        dollars_part, cents_part = num_str.split('.', 1)
    else:
        dollars_part = num_str
        cents_part = ''

    # Pad or truncate cents to exactly 2 digits
    if len(cents_part) == 0:
        cents_part = '00'
    elif len(cents_part) == 1:
        cents_part = cents_part + '0'
    elif len(cents_part) > 2:
        cents_part = cents_part[:2]

    # Remove any leading zeros from dollars_part while handling zero
    dollars_part = dollars_part.lstrip('0') or '0'

    # Combine to get total minor units (cents) as string
    if dollars_part == '0':
        minor_str = cents_part.lstrip('0') or '0'
    else:
        minor_str = dollars_part + cents_part

    # Calculate Luhn-style check digit: sum of digits mod 10
    digit_sum = sum(int(ch) for ch in minor_str)
    check = digit_sum % 10

    return f"{sign}{minor_str}#{check}"

