def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    negative = False
    if s[0] in "+-":
        negative = s[0] == "-"
        s = s[1:]

    if not s:
        raise ValueError("missing digits")

    if s.count(".") > 1:
        raise ValueError("invalid amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "" and frac == "":
        raise ValueError("missing digits")

    if whole and not whole.isdigit():
        raise ValueError("invalid dollar digits")
    if frac and not frac.isdigit():
        raise ValueError("invalid cent digits")
    if len(frac) > 2:
        raise ValueError("too many fractional digits")

    whole = whole or "0"
    frac = frac.ljust(2, "0")

    cents_value = int(whole) * 100 + int(frac or "0")
    digits = str(cents_value)

    sign = "-" if negative and cents_value != 0 else "+"
    check = sum(int(ch) for ch in digits) % 10

    return f"{sign}{digits}#{check}"

