                        "description": "The memo for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with reason '{reason}' and return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use = next(block for block in response.content if block.type == "tool_use")
        tool_name = tool_use.name
        tool_input = tool_use.input

        if tool_name == "post":
            entry_id = f"entry_{acct}_{cents}_{hash(reason) % 10000}"
            tool_result = {
                "entry_id": entry_id,
                "status": "success",
                "account": tool_input.get("account"),
                "amount": tool_input.get("amount"),
                "memo": tool_input.get("memo")
            }

            messages.append({"role": "assistant", "content": response.content})
            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use.id,
                        "content": json.dumps(tool_result)
                    }
                ]
            })

            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=tools,
                messages=messages
            )

    final_text = next(
        (block.text for block in response.content if hasattr(block, "text")),
        None
    )

    if "entry_" in final_text:
        for word in final_text.split():
            if word.startswith("entry_"):
                return word.rstrip(".,;:")

    return f"entry_{acct}_{cents}_{hash(reason) % 10000}"

