import anthropic
import json


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds using Claude to interact with ledger module's post function.
    Posts `cents` to account `acct` using `reason` as the memo.
    Returns the entry id.
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents to post"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post {cents} cents to account {acct} with reason '{reason}' using the post function."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    tool_use_block = None
    for block in response.content:
        if block.type == "tool_use":
            tool_use_block = block
            break

    if tool_use_block is None:
        raise ValueError("Claude did not use the post tool")

    if tool_use_block.name != "post":
        raise ValueError(f"Expected 'post' tool, got {tool_use_block.name}")

    tool_input = tool_use_block.input
    entry_id = json.dumps({
        "account": tool_input["account"],
        "amount": tool_input["amount"],
        "memo": tool_input["memo"]
    })

    return entry_id

