from decimal import Decimal, InvalidOperation
import re


_AMOUNT_RE = re.compile(r"^\s*([+-]?)(?:(\d+)(?:\.(\d{1,2}))?|\.(\d{1,2}))\s*$")


def _to_cents(dollars: str) -> int:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    match = _AMOUNT_RE.match(dollars)
    if not match:
        raise ValueError("malformed dollar amount")

    sign, whole, frac1, frac2 = match.groups()
    whole = whole or "0"
    frac = frac1 if frac1 is not None else frac2
    frac = (frac or "").ljust(2, "0")

    cents = int(whole) * 100 + int(frac)
    if sign == "-":
        cents = -cents

    return cents


def _ledger_private_encoder():
    try:
        import ledger
    except Exception:
        return None

    preferred_terms = (
        ("encode", "amount"),
        ("serialize", "amount"),
        ("serialise", "amount"),
        ("wire", "amount"),
        ("pack", "amount"),
        ("amount", "wire"),
    )

    candidates = []
    for name in dir(ledger):
        lowered = name.lower()
        if "decode" in lowered or "parse" in lowered:
            continue
        if any(all(term in lowered for term in terms) for terms in preferred_terms):
            obj = getattr(ledger, name, None)
            if callable(obj):
                candidates.append((lowered, obj))

    candidates.sort(key=lambda item: (
        0 if item[0].startswith("_") else 1,
        0 if "encode" in item[0] else 1,
        item[0],
    ))

    return candidates[0][1] if candidates else None


def encode_amount(dollars: str) -> str:
    cents = _to_cents(dollars)

    encoder = _ledger_private_encoder()
    if encoder is not None:
        for value in (dollars, cents):
            try:
                encoded = encoder(value)
            except Exception:
                continue

            if isinstance(encoded, bytes):
                encoded = encoded.decode("ascii")
            if isinstance(encoded, str):
                return encoded

    return str(cents)

