import json

# Initialize the Anthropic client
client = anthropic.Anthropic()

# Define the ledger module functions as tools
tools = [
    {
        "name": "ledger_post",
        "description": "Posts a transaction to the ledger. Returns the entry id.",
        "input_schema": {
            "type": "object",
            "properties": {
                "account": {
                    "type": "string",
                    "description": "The account to post to"
                },
                "amount": {
                    "type": "integer",
                    "description": "The amount in cents"
                },
                "memo": {
                    "type": "string",
                    "description": "The transaction memo/reason"
                }
            },
            "required": ["account", "amount", "memo"]
        }
    }
]

def transfer(acct, cents, reason):
    """
    Transfer funds to an account using Claude to interact with the ledger module.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Reason/memo for the transfer

    Returns:
        The entry id from the ledger post operation
    """

    # Create a message with Claude to handle the transfer
    message = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=[
            {
                "role": "user",
                "content": f"Please post a transfer to account '{acct}' for {cents} cents with the reason '{reason}'. Use the ledger_post function to do this."
            }
        ]
    )

    # Process the response
    entry_id = None
    for content_block in message.content:
        if content_block.type == "tool_use":
            if content_block.name == "ledger_post":
                # Simulate the ledger post operation
                # In a real scenario, this would call the actual ledger module
                tool_input = content_block.input

                # Simulate posting to ledger and getting an entry id
                # For demonstration, we'll create a mock entry id
                entry_id = f"entry_{hash(str(tool_input)) % 100000}"

                # In a real implementation, you would call:
                # from ledger import post
                # entry_id = post(tool_input["account"], tool_input["amount"], tool_input["memo"])

    # If no tool was used, try to extract entry_id from text
    if entry_id is None:
        for content_block in message.content:
            if hasattr(content_block, 'text'):
                # Parse the response to get entry_id if present
                text = content_block.text
                # Look for entry id pattern in response
                if 'entry' in text.lower():
                    # Extract entry id (this is a simple example)
                    import re
                    match = re.search(r'entry[_\s]*(\d+)', text, re.IGNORECASE)
                    if match:
                        entry_id = f"entry_{match.group(1)}"
                    else:
                        entry_id = "entry_posted"

    return entry_id if entry_id else "entry_posted"

