def encode_amount(dollars: str) -> str:
    """Serialize a money amount string to the team's private wire format."""
    sign_char = ''
    num_str = dollars

    if num_str.startswith('+'):
        num_str = num_str[1:]
    elif num_str.startswith('-'):
        sign_char = '-'
        num_str = num_str[1:]

    if '.' in num_str:
        integer_part, fractional_part = num_str.split('.', 1)
    else:
        integer_part, fractional_part = num_str, ''

    integer_part = integer_part.lstrip('0') or '0'

    if fractional_part:
        fractional_part = fractional_part.rstrip('0')

    if fractional_part:
        result = f"{sign_char}{integer_part}.{fractional_part}"
    else:
        result = f"{sign_char}{integer_part}"

    if result in ('', '-', '.'):
        result = '0'
    elif result == '-0':
        result = '0'

    return result

