from decimal import Decimal, InvalidOperation, ROUND_DOWN

try:
    import ledger as _ledger
    _PostError = _ledger.PostError
except Exception:
    class _PostError(ValueError):
        pass


def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise _PostError("malformed amount")

    text = dollars.strip()
    if not text:
        raise _PostError("malformed amount")

    try:
        value = Decimal(text)
    except (InvalidOperation, ValueError):
        raise _PostError("malformed amount")

    if not value.is_finite():
        raise _PostError("malformed amount")

    cents = value * Decimal("100")
    if cents != cents.to_integral_value(rounding=ROUND_DOWN):
        raise _PostError("malformed amount")

    cents_int = int(cents)
    return str(cents_int)

