def encode_amount(dollars: str) -> str:
    """Serialize a money amount string (e.g. '12.30', '-0.07') to the wire format.

    The wire format encodes the amount as an integer number of cents, as a
    decimal string. This avoids floating point ambiguity on the wire.
    """
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    negative = False
    if s[0] in "+-":
        negative = s[0] == "-"
        s = s[1:]

    if not s:
        raise ValueError("malformed amount: no digits")

    if "." in s:
        whole, _, frac = s.partition(".")
    else:
        whole, frac = s, ""

    if whole == "" and frac == "":
        raise ValueError("malformed amount")

    if whole == "":
        whole = "0"

    if not whole.isdigit():
        raise ValueError("malformed amount: non-digit in whole part")
    if frac != "" and not frac.isdigit():
        raise ValueError("malformed amount: non-digit in fractional part")

    # Normalize fractional part to exactly 2 digits (cents).
    if len(frac) > 2:
        # Reject more precision than cents rather than silently truncating.
        raise ValueError("malformed amount: sub-cent precision not supported")
    frac = (frac + "00")[:2]

    cents = int(whole) * 100 + int(frac)
    if negative:
        cents = -cents

    return str(cents)

