import anthropic
import json

client = anthropic.Anthropic()
ledger = None

def setup_ledger():
    """Setup the ledger module reference for Claude to use."""
    global ledger
    import sys
    import importlib.util

    # Load the ledger module
    spec = importlib.util.spec_from_file_location("ledger", "ledger.py")
    ledger = importlib.util.module_from_file_location("ledger", spec)
    spec.loader.exec_module(ledger)

def transfer(acct, cents, reason):
    """Transfer funds to an account using Claude to call the ledger post function."""
    if ledger is None:
        setup_ledger()

    tools = [
        {
            "name": "post_to_ledger",
            "description": "Post a transaction to the ledger system",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post {cents} cents to account {acct} with reason '{reason}' using the post function from the ledger module. Return the entry id."
        }
    ]

    while True:
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        if response.stop_reason == "tool_use":
            tool_use_block = None
            for block in response.content:
                if hasattr(block, 'type') and block.type == "tool_use":
                    tool_use_block = block
                    break

            if tool_use_block and tool_use_block.name == "post_to_ledger":
                account = tool_use_block.input["account"]
                amount = tool_use_block.input["amount"]
                memo = tool_use_block.input["memo"]

                entry_id = ledger.post(account, amount, memo)

                messages.append({"role": "assistant", "content": response.content})
                messages.append({
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": tool_use_block.id,
                            "content": f"Successfully posted {amount} cents to account {account} with memo '{memo}'. Entry ID: {entry_id}"
                        }
                    ]
                })
        else:
            for block in response.content:
                if hasattr(block, 'text'):
                    text = block.text
                    if "Entry ID:" in text or "entry id:" in text.lower():
                        import re
                        match = re.search(r'[Ee]ntry\s+[Ii][Dd]:\s*(\d+)', text)
                        if match:
                            return int(match.group(1))
                    elif text.isdigit():
                        return int(text)
            return None

if __name__ == "__main__":
    entry_id = transfer("checking", 5000, "Monthly salary deposit")
    print(f"Transfer completed with entry ID: {entry_id}")
