def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds using Claude to interact with a ledger system.

    Args:
        acct: The account to post to
        cents: The amount in cents
        reason: The memo/reason for the transaction

    Returns:
        The entry id from the ledger
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "ledger_post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with reason '{reason}' using the ledger_post function. Return only the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process tool use
    entry_id = None
    while response.stop_reason == "tool_use":
        tool_use_block = None
        for block in response.content:
            if block.type == "tool_use":
                tool_use_block = block
                break

        if tool_use_block is None:
            break

        # Simulate the ledger post function
        tool_input = tool_use_block.input
        simulated_result = {
            "entry_id": f"entry_{acct}_{cents}_{hash(reason) % 10000}",
            "account": tool_input.get("account"),
            "amount": tool_input.get("amount"),
            "memo": tool_input.get("memo"),
            "status": "posted"
        }
        entry_id = simulated_result["entry_id"]

        # Continue conversation with tool result
        messages.append({"role": "assistant", "content": response.content})
        messages.append({
            "role": "user",
            "content": [
                {
                    "type": "tool_result",
                    "tool_use_id": tool_use_block.id,
                    "content": json.dumps(simulated_result)
                }
            ]
        })

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

    # Extract entry id from final response
    if entry_id:
        return entry_id

    # Try to extract from response text if not found
    for block in response.content:
        if hasattr(block, 'text'):
            # Look for entry id pattern in response
            match = re.search(r'entry_\w+', block.text)
            if match:
                return match.group(0)
            # Look for any id-like pattern
            match = re.search(r'id[:\s]+(\S+)', block.text, re.IGNORECASE)
            if match:
                return match.group(1)

    return "entry_default"


if __name__ == "__main__":
    # Test the transfer function
    entry_id = transfer("checking", 10000, "Monthly salary")
    print(f"Entry ID: {entry_id}")
