import re

def encode_amount(dollars: str) -> str:
    # Remove any whitespace
    dollars = dollars.strip()
    if not dollars:
        raise ValueError("Empty input")

    # Determine sign
    sign = '+'
    if dollars[0] == '-':
        sign = '-'
        dollars = dollars[1:]

    # Parse dollars and cents
    if '.' in dollars:
        parts = dollars.split('.')
        if len(parts) != 2:
            raise ValueError("Invalid amount format")
        whole, frac = parts
        if len(frac) < 2:
            frac = frac.ljust(2, '0')
        elif len(frac) > 2:
            raise ValueError("Too many decimal places")
    else:
        whole = dollars
        frac = '00'

    # Validate that whole part is digits
    if not whole.isdigit():
        raise ValueError("Invalid characters in amount")
    if not frac.isdigit() or len(frac) != 2:
        raise ValueError("Invalid fractional part")

    # Convert to total cents as string
    total_cents = int(whole) * 100 + int(frac)
    if total_cents == 0:
        digits_str = "0"
    else:
        digits_str = str(total_cents)

    # Calculate check digit
    digit_sum = sum(int(c) for c in digits_str)
    check = digit_sum % 10

    return f"{sign}{digits_str}#{check}"

