def encode_amount(dollars: str) -> str:
    # Determine sign
    if dollars.startswith('-'):
        sign = '-'
        numeric_str = dollars[1:]
    else:
        sign = '+'
        numeric_str = dollars

    # Split into integer and fractional parts
    if '.' in numeric_str:
        int_part, frac_part = numeric_str.split('.', 1)
    else:
        int_part = numeric_str
        frac_part = ''

    # Normalize fractional part to exactly 2 digits
    if len(frac_part) == 0:
        frac_part = '00'
    elif len(frac_part) == 1:
        frac_part = frac_part + '0'
    elif len(frac_part) > 2:
        # Handle extra precision by truncating (or could round, but spec implies exact cents)
        frac_part = frac_part[:2]

    # Combine to get minor units string (remove leading zeros from int_part before combining, but preserve at least one zero)
    if int_part == '' or int_part == '0':
        minor_str = frac_part
    else:
        minor_str = int_part.lstrip('0') + frac_part

    # Remove leading zeros while ensuring at least one digit remains
    minor_str = minor_str.lstrip('0')
    if minor_str == '':
        minor_str = '0'

    digits = minor_str

    # Compute check digit: sum of decimal digits mod 10
    check = sum(int(d) for d in digits) % 10

    return f"{sign}{digits}#{check}"

