def encode_amount(dollars: str) -> str:
    """
    Serialize a money amount string ('12.30', '-0.07') to the
    house-private wire format.
    """
    sign = ""
    if dollars.startswith("-"):
        sign = "-"
        dollars = dollars[1:]
    elif dollars.startswith("+"):
        dollars = dollars[1:]

    if "." in dollars:
        whole, cents = dollars.split(".", 1)
        if len(cents) == 1:
            cents += "0"
        elif len(cents) > 2:
            cents = cents[:2]
    else:
        whole = dollars
        cents = "00"

    whole = whole.lstrip("0") or "0"
    return f"{sign}{whole}.{cents}"

