import anthropic
import json


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer cents to account using reason as memo via Claude.

    Args:
        acct: Account identifier
        cents: Amount in cents
        reason: Memo/reason for transfer

    Returns:
        Entry ID from the ledger post
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "ledger_post",
            "description": "Post a transfer to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account identifier"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "Amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "Reason/memo for the transfer"
                    }
                },
                "required": ["account", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post a transfer of {cents} cents to account {acct} with reason '{reason}' and return the entry ID."
        }
    ]

    # Agentic loop
    while True:
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        if response.stop_reason == "tool_use":
            # Process tool use
            tool_use_block = None
            for block in response.content:
                if block.type == "tool_use":
                    tool_use_block = block
                    break

            if tool_use_block:
                # Simulate the ledger post operation
                tool_input = tool_use_block.input

                # Simulate posting to ledger and getting entry ID
                entry_id = f"entry_{hash(f'{tool_input.get(\"account\", \"\")}_{tool_input.get(\"cents\", 0)}_{tool_input.get(\"memo\", \"\")}') % 1000000}"

                # Add assistant response and tool result to messages
                messages.append({"role": "assistant", "content": response.content})
                messages.append({
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": tool_use_block.id,
                            "content": json.dumps({"entry_id": entry_id})
                        }
                    ]
                })
        else:
            # Model has finished or provided final answer
            for block in response.content:
                if hasattr(block, "text"):
                    # Try to extract entry ID from response
                    text = block.text
                    if "entry_" in text:
