from decimal import Decimal, InvalidOperation


class EncodeError(Exception):
    """Raised when a money amount cannot be encoded to the wire format."""


def encode_amount(dollars: str) -> str:
    """Serialize a money amount (e.g. '12.30', '-0.07') to the wire format.

    The wire format is canonical signed integer cents, e.g.:
        '12.30'  -> 'c:1230'
        '-0.07'  -> 'c:-7'
        '0.00'   -> 'c:0'

    Raises EncodeError on malformed input.
    """
    if not isinstance(dollars, str):
        raise EncodeError("amount must be a string")

    s = dollars.strip()
    if s == "":
        raise EncodeError("empty amount")

    try:
        value = Decimal(s)
    except (InvalidOperation, ValueError) as exc:
        raise EncodeError(f"malformed amount: {dollars!r}") from exc

    if not value.is_finite():
        raise EncodeError(f"non-finite amount: {dollars!r}")

    # Convert to integer cents (quantize to 2 decimal places).
    try:
        cents = int((value * 100).to_integral_value())
    except (InvalidOperation, ValueError) as exc:
        raise EncodeError(f"uncoercible amount: {dollars!r}") from exc

    # Reject amounts with sub-cent precision to avoid silent rounding.
    if (value * 100) != Decimal(cents):
        raise EncodeError(f"sub-cent precision not allowed: {dollars!r}")

    return f"c:{cents}"

