                    "role": "assistant",
                    "content": response.content
                })

                messages.append({
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": block.id,
                            "content": json.dumps({
                                "status": "success",
                                "entry_id": entry_id,
                                "message": f"Successfully posted {cents} cents to {acct}"
                            })
                        }
                    ]
                })

                # Get Claude's final response
                final_response = client.messages.create(
                    model="claude-3-5-sonnet-20241022",
                    max_tokens=1024,
                    tools=tools,
                    messages=messages
                )

                # Extract entry_id from the final response if needed
                for final_block in final_response.content:
                    if hasattr(final_block, 'text'):
                        # Try to extract entry_id from the text response
                        text = final_block.text
                        # Look for entry_id patterns
                        match = re.search(r'entry_\d+', text)
