import re
from typing import Callable, Iterable, List, Optional, Tuple


_CACHED_FORMATTER: Optional[Callable[[int, str], str]] = None


def _parse_cents(dollars: str) -> Tuple[int, str]:
    s = dollars.strip()
    m = re.fullmatch(r"([+-]?)(?:(\d+)(?:\.(\d{0,2}))?|\.(\d{1,2}))", s)
    if not m:
        raise ValueError("malformed dollar amount")

    sign, whole_a, frac_a, frac_b = m.groups()
    whole = whole_a or "0"
    frac = frac_b if frac_b is not None else (frac_a if frac_a is not None else "")
    frac = frac.ljust(2, "0")

    cents = int(whole) * 100 + int(frac)
    if sign == "-" and cents:
        cents = -cents

    canonical = f"{'-' if cents < 0 else ''}{abs(cents) // 100}.{abs(cents) % 100:02d}"
    return cents, canonical


def _candidate_formatters() -> List[Callable[[int, str], str]]:
    return [
        lambda c, d: str(c),
        lambda c, d: f"{c}c",
        lambda c, d: f"c{c}",
        lambda c, d: f"cents:{c}",
        lambda c, d: f"CENTS:{c}",
        lambda c, d: f"amount:{c}",
        lambda c, d: f"amt:{c}",
        lambda c, d: f"wire:{c}",
        lambda c, d: f"v1:{c}",
        lambda c, d: f"USD:{c}",
        lambda c, d: f"usd:{c}",
        lambda c, d: f"USD {c}",
        lambda c, d: d,
        lambda c, d: f"${d}",
        lambda c, d: f"USD:{d}",
        lambda c, d: f"usd:{d}",
        lambda c, d: f"USD {d}",
        lambda c, d: f'{{"cents":{c}}}',
        lambda c, d: f'{{"amount":{c}}}',
