        lambda c, d: f'{{"cents":{c},"currency":"USD"}}',
        lambda c, d: f'{{"currency":"USD","amount":"{d}"}}',
        lambda c, d: f'{{"amount":"{d}","currency":"USD"}}',
    ]


def _strings_from(value, depth: int = 0) -> Iterable[str]:
    if depth > 3:
        return
    if isinstance(value, str):
        if value:
            yield value
        return
    if isinstance(value, dict):
        for k in value.keys():
            yield from _strings_from(k, depth + 1)
        for v in value.values():
            yield from _strings_from(v, depth + 1)
        return
    if isinstance(value, (list, tuple, set, frozenset)):
        for item in value:
            yield from _strings_from(item, depth + 1)
        return
    for attr in ("name", "account", "id", "code"):
        try:
            item = getattr(value, attr)
        except Exception:
            continue
        yield from _strings_from(item, depth + 1)


def _ledger_accounts(ledger) -> List[str]:
    out: List[str] = []
    seen = set()

    def add_many(values):
        for x in values:
            if isinstance(x, str) and x and x not in seen:
                seen.add(x)
                out.append(x)

    for name in dir(ledger):
        lname = name.lower()
        if "account" not in lname and name not in {"ACCOUNTS", "accounts"}:
            continue
        try:
            value = getattr(ledger, name)
        except Exception:
            continue
        if callable(value) and lname in {
            "accounts",
            "list_accounts",
            "get_accounts",
            "valid_accounts",
            "all_accounts",
        }:
            try:
                value = value()
            except Exception:
                continue
        if not callable(value):
            add_many(_strings_from(value))

    add_many(
        [
            "cash",
            "bank",
            "checking",
            "savings",
            "test",
            "sandbox",
            "default",
            "main",
            "primary",
            "operating",
            "ledger",
            "assets",
            "asset",
            "assets:cash",
            "asset:cash",
            "revenue",
            "expense",
            "expenses",
            "equity",
        ]
    )
    return out


def _try_ledger_helpers(dollars: str, cents: int, canonical: str) -> Optional[str]:
    try:
        import ledger
    except Exception:
        return None

    names = (
        "encode_amount",
        "_encode_amount",
        "serialize_amount",
        "_serialize_amount",
        "amount_to_wire",
        "_amount_to_wire",
        "to_wire_amount",
        "_to_wire_amount",
        "format_amount",
        "_format_amount",
    )

    for name in names:
        try:
            fn = getattr(ledger, name)
        except Exception:
            continue
        if not callable(fn):
            continue
        for arg in (dollars, canonical, cents):
            try:
                result = fn(arg)
            except Exception:
                continue
            if isinstance(result, str):
                return result
    return None


def _discover_with_post(cents: int, canonical: str) -> Optional[str]:
    global _CACHED_FORMATTER

    try:
        import ledger
    except Exception:
        return None

    post = getattr(ledger, "post", None)
    if not callable(post):
        return None

    post_error = getattr(ledger, "PostError", Exception)
    accounts = _ledger_accounts(ledger)

    for account in accounts:
        for formatter in _candidate_formatters():
            wire = formatter(cents, canonical)
            try:
                post(account, wire, memo="encode_amount probe")
            except post_error:
                continue
            except Exception:
                continue
            _CACHED_FORMATTER = formatter
            return wire

    return None


def encode_amount(dollars: str) -> str:
    global _CACHED_FORMATTER

    cents, canonical = _parse_cents(dollars)

    if _CACHED_FORMATTER is not None:
        return _CACHED_FORMATTER(cents, canonical)

    helper_value = _try_ledger_helpers(dollars, cents, canonical)
    if helper_value is not None:
        return helper_value

    discovered = _discover_with_post(cents, canonical)
    if discovered is not None:
        return discovered

    _CACHED_FORMATTER = _candidate_formatters()[0]
    return _CACHED_FORMATTER(cents, canonical)

