def _wire_to_cents(wire: str) -> int:
    """Validate wire format and return signed cents."""
    if not wire or '#' not in wire:
        raise ValueError(f"Invalid wire format: {wire!r}")
    body, _, check_str = wire.partition('#')
    sign_char = body[0]
    if sign_char not in ('+', '-'):
        raise ValueError(f"Invalid sign: {wire!r}")
    digits = body[1:]
    if not digits.isdigit():
        raise ValueError(f"Invalid digits: {wire!r}")
    if not check_str.isdigit() or len(check_str) != 1:
        raise ValueError(f"Invalid check digit: {wire!r}")
    computed = sum(int(d) for d in digits) % 10
    if computed != int(check_str):
        raise ValueError(f"Check digit mismatch: {wire!r}")
    amount = int(digits)
    return amount if sign_char == '+' else -amount

def _as_cents(value) -> int:
    """Convert dollars (float/Decimal/int) or cents (int) to exact cents."""
    if isinstance(value, int):
        # assume already in cents
        return value
    if isinstance(value, float):
        value = Decimal(str(value))
    elif not isinstance(value, Decimal):
        value = Decimal(value)
    # Quantize to cents using banker's rounding
    cents = value.quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
    return int(cents * 100)

def record(acct: str, cents, note: str = ""):
    """Post `cents` to account `acct` with memo `note`. Returns new entry id."""
    import solution  # ledger module provided in the environment (private context)

    # Normalize cents to integer minor units
    if not isinstance(cents, int):
        cents = _as_cents(cents)

    wire = _amount_to_wire(cents)
    # The ledger.post function is expected to accept the wire-encoded amount.
    # Per the invariant, the posting function accepts the wire string directly.
    return solution.post(acct, wire, note)

def encode_amount(dollars: str) -> str:
    """Serialize a money amount string (e.g. '12.30', '-0.07') to the wire format.

    The wire format represents the amount as an integer number of cents,
    preserving sign. Examples:
        '12.30'  -> '1230'
        '-0.07'  -> '-7'
        '0.00'   -> '0'
    """
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    negative = False
    if s[0] in "+-":
        negative = s[0] == "-"
        s = s[1:]

    if "." in s:
        whole, _, frac = s.partition(".")
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    # Normalize fractional part to exactly two digits (cents).
    if len(frac) > 2:
        # Reject sub-cent precision rather than silently truncating.
        raise ValueError(f"too many fractional digits: {dollars!r}")
    frac = (frac + "00")[:2]

    if not whole.isdigit() or not frac.isdigit():
        raise ValueError(f"malformed amount: {dollars!r}")

    cents = int(whole) * 100 + int(frac)
    if negative:
        cents = -cents

    return str(cents)

