def encode_amount(dollars: str) -> str:
    s = str(dollars).strip()
    if not s:
        raise ValueError("empty amount")

    sign = "+"
    sign_seen = False

    if s[0] in "+-":
        sign = s[0]
        sign_seen = True
        s = s[1:].strip()

    if s.startswith("$"):
        s = s[1:].strip()

    if s and s[0] in "+-":
        if sign_seen:
            raise ValueError("multiple signs")
        sign = s[0]
        s = s[1:].strip()

    if not s:
        raise ValueError("missing numeric amount")

    if s.count(".") > 1:
        raise ValueError("invalid decimal amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "" and frac == "":
        raise ValueError("missing numeric amount")

    if whole == "":
        whole = "0"

    if not all("0" <= c <= "9" for c in whole):
        raise ValueError("invalid dollar digits")

    if frac and not all("0" <= c <= "9" for c in frac):
        raise ValueError("invalid cent digits")

    if len(frac) > 2:
        if any(c != "0" for c in frac[2:]):
            raise ValueError("amount has sub-cent precision")
        frac = frac[:2]

    frac = frac.ljust(2, "0")

    cents = int(whole) * 100 + int(frac)
    digits = str(cents)
    check = sum(ord(c) - ord("0") for c in digits) % 10

    return f"{sign}{digits}#{check}"

