client = anthropic.Anthropic()

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds to an account using the ledger module's post function.

    Args:
        acct: Account identifier
        cents: Amount in cents
        reason: Memo/reason for the transfer

    Returns:
        The entry id from the ledger post operation
    """

    # Define the tools available to Claude
    tools = [
        {
            "name": "post",
            "description": "Posts a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "Amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "Transaction memo/reason"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    # Create the initial message to Claude
    messages = [
        {
            "role": "user",
            "content": f"Please post a transfer of {cents} cents to account {acct} with the reason '{reason}' using the post function. Return the entry id."
        }
    ]

    # Agentic loop to handle tool calls
    while True:
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

