                    tool_name = content_block.name
                    tool_input = content_block.input
                    tool_use_id = content_block.id

                    # Simulate the post function behavior
                    if tool_name == "post":
                        # Simulate posting to ledger and generate entry id
                        entry_id = f"entry_{abs(hash((tool_input['account'], tool_input['amount'], tool_input['memo']))) % 10000000}"
                        tool_results.append({
                            "type": "tool_result",
                            "tool_use_id": tool_use_id,
                            "content": json.dumps({"entry_id": entry_id})
                        })

            # Add assistant response and tool results to messages
            messages.append({"role": "assistant", "content": response.content})
            messages.append({"role": "user", "content": tool_results})

        else:
            # Claude has finished, extract the entry id from the response
            for content_block in response.content:
                if hasattr(content_block, 'text'):
                    text = content_block.text
                    # Try to extract entry_id from the response
