import anthropic


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds using Claude to interact with the ledger module.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Memo/reason for the transfer

    Returns:
        The entry id from the ledger post operation
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "Account identifier"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "Amount in cents"
                    },
                    "reason": {
                        "type": "string",
                        "description": "Memo or reason for the transaction"
                    }
                },
                "required": ["acct", "cents", "reason"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post a transfer of {cents} cents to account {acct} with the reason: {reason}. Use the post tool to complete this transaction."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process tool calls
    while response.stop_reason == "tool_use":
        # Find the tool use block
        tool_use_block = None
        for block in response.content:
            if block.type == "tool_use":
                tool_use_block = block
                break

        if tool_use_block is None:
            raise ValueError("Expected tool_use block but none found")

        # Simulate the ledger.post function
        # In a real scenario, this would call the actual ledger module
        entry_id = f"entry_{acct}_{cents}_{hash(reason) & 0xFFFFFFFF:08x}"

        # Add assistant response and tool result to messages
        messages.append({
            "role": "assistant",
            "content": response.content
        })

        messages.append({
            "role": "user",
            "content": [
                {
                    "type": "tool_result",
                    "tool_use_id": tool_use_block.id,
                    "content": entry_id
                }
            ]
        })

        # Get the next response
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

    # Extract the entry id from the final response
    for block in response.content:
        if hasattr(block, "text"):
            # Try to extract entry id from the response text
            text = block.text
            if "entry_" in text:
                # Simple extraction - in real scenario might need more robust parsing
                import re
                match = re.search(r"entry_[a-zA-Z0-9_]+", text)
                if match:
                    return match.group(0)

    # Return the entry id we generated
    return f"entry_{acct}_{cents}_{hash(reason) & 0xFFFFFFFF:08x}"

