def encode_amount(dollars: str) -> str:
    """Serialize a money amount string to the team's private wire format.

    Accepts strings like '12.30' or '-0.07' and returns a normalized
    wire representation. Normalizes sign, pads/truncates to exactly
    two fractional digits, and strips insignificant leading zeros from
    the integer part (while keeping at least one).
    """
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = ""
    if s[0] in "+-":
        if s[0] == "-":
            sign = "-"
        s = s[1:]

    if not s:
        raise ValueError("missing digits")

    if "." in s:
        int_part, _, frac_part = s.partition(".")
        if "." in frac_part:
            raise ValueError("too many decimal points")
    else:
        int_part, frac_part = s, ""

    int_part = int_part or "0"
    if not int_part.isdigit():
        raise ValueError("invalid integer part")
    if frac_part and not frac_part.isdigit():
        raise ValueError("invalid fractional part")

    # normalize fractional part to exactly two digits
    frac_part = (frac_part + "00")[:2]

    # strip leading zeros but keep at least one digit
    int_part = int_part.lstrip("0") or "0"

    # drop sign for a zero value
    if int_part == "0" and frac_part == "00":
        sign = ""

    return f"{sign}{int_part}.{frac_part}"

