def encode_amount(dollars: str) -> str:
    """
    Serialize a money amount string (e.g., '12.30', '-0.07') to a private wire format.
    The format is: 'A' + adjusted_integer_part
    - Positive amounts: 'A' + string of amount * 100 (integer, no decimal point)
    - Negative amounts: 'A-' + string of abs(amount) * 100
    - Zero: 'A0'
    """
    amount = dollars.strip()
    if not amount:
        raise ValueError("Empty amount string")

    # Check for negative sign
    negative = amount.startswith('-')
    if negative:
        amount = amount[1:]

    # Split into dollars and cents
    if '.' in amount:
        dollars_part, cents_part = amount.split('.', 1)
    else:
        dollars_part = amount
        cents_part = ''

    # Pad or truncate cents to exactly 2 digits
    if len(cents_part) == 0:
        cents = 0
    elif len(cents_part) == 1:
        cents = int(cents_part) * 10
    elif len(cents_part) == 2:
        cents = int(cents_part)
    else:
        # More than 2 decimal places: truncate, don't round
        cents = int(cents_part[:2])

    # Combine dollars and cents into total cents (integer)
    dollars_int = int(dollars_part) if dollars_part else 0
    total_cents = dollars_int * 100 + cents

    # Apply sign
    if negative:
        total_cents = -total_cents

    # Encode
    if total_cents == 0:
        return 'A0'
    elif total_cents > 0:
        return 'A' + str(total_cents)
    else:
        return 'A-' + str(abs(total_cents))

