import anthropic
import json

client = anthropic.Anthropic()

def transfer(acct: str, cents: int, reason: str) -> str:
    """Transfer funds using the ledger module and return the entry id."""

    tools = [
        {
            "name": "post",
            "description": "Posts an entry to the ledger with the given account, amount in cents, and memo",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo for the entry"
                    }
                },
                "required": ["acct", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with the reason '{reason}' and tell me the entry id that was returned."
        }
    ]

    while True:
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        if response.stop_reason == "tool_use":
            tool_use_block = None
            for block in response.content:
                if block.type == "tool_use":
                    tool_use_block = block
                    break

            if tool_use_block:
                tool_name = tool_use_block.name
                tool_input = tool_use_block.input

                if tool_name == "post":
                    result = post(
                        acct=tool_input["acct"],
                        cents=tool_input["cents"],
                        memo=tool_input["memo"]
                    )

                    messages.append({"role": "assistant", "content": response.content})
                    messages.append({
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": tool_use_block.id,
                                "content": json.dumps({"entry_id": result})
                            }
                        ]
                    })
        else:
            for block in response.content:
                if hasattr(block, 'text'):
                    text = block.text
                    if "entry" in text.lower() and "id" in text.lower():
                        import re
                        numbers = re.findall(r'\b\d+\b', text)
                        if numbers:
                            return numbers[-1]

            return ""


