        if hasattr(block, "text"):
            text = block.text
            # Look for entry_id in the response
            if "entry_" in text:
                # Extract entry ID from the response
                import re
                match = re.search(r'entry_\d+', text)
                if match:
                    return match.group(0)

    # Fallback: generate entry ID based on inputs
    return f"entry_{abs(hash((acct, cents, reason))) % 10000}"


