import re

try:
    import ledger as _ledger
    _PostError = _ledger.PostError
except Exception:
    class _PostError(Exception):
        pass


_AMOUNT_RE = re.compile(r"^[+-]?(?:(?:\d+(?:\.\d{0,2})?)|(?:\.\d{1,2}))$")


def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise _PostError("malformed amount")

    s = dollars.strip()
    if not s or not _AMOUNT_RE.fullmatch(s):
        raise _PostError("malformed amount")

    negative = s.startswith("-")
    if s[0:1] in "+-":
        s = s[1:]

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if not whole:
        whole = "0"

    frac = (frac + "00")[:2]
    cents = int(whole) * 100 + int(frac)

    if negative and cents:
        cents = -cents

    return str(cents)

