import anthropic
import ledger


def transfer(acct: str, cents: int, reason: str) -> int:
    """
    Transfer cents to an account using the ledger module.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Reason/memo for the transfer

    Returns:
        The entry id returned by ledger.post()

    Raises:
        ledger.PostError: If the ledger operation fails
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "ledger_post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo or reason for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please transfer {cents} cents to account {acct} with reason: {reason}"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use_block = next(
            (block for block in response.content if block.type == "tool_use"),
            None
        )

        if tool_use_block and tool_use_block.name == "ledger_post":
            input_params = tool_use_block.input
            entry_id = ledger.post(
                input_params["account"],
                input_params["amount"],
                memo=input_params["memo"]
            )

            messages.append({
                "role": "assistant",
                "content": response.content
            })

            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use_block.id,
                        "content": str(entry_id)
                    }
                ]
            })

            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=tools,
                messages=messages
            )
        else:
            break

    return entry_id

