from decimal import Decimal, InvalidOperation

def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise TypeError("Amount must be a string")

    s = dollars.strip()
    if not s:
        raise ValueError("Empty amount")

    sign = "+"
    if s[0] in "+-":
        sign = s[0]
        s = s[1:]

    if s.startswith("$"):
        s = s[1:]

    if not s:
        raise ValueError("Missing numeric value")

    try:
        value = Decimal(s)
    except InvalidOperation:
        raise ValueError(f"Invalid amount: {dollars}")

    if not value.is_finite() or value < 0:
        raise ValueError("Invalid amount")

    cents = int(value * 100)
    digits = str(cents)
    check = sum(int(ch) for ch in digits) % 10

    return f"{sign}{digits}#{check}"

