import re

_AMOUNT_RE = re.compile(r"^([+-]?)(?:(\d+)(?:\.(\d{0,2}))?|\.(\d{1,2}))$")


def _malformed_amount(message="malformed amount"):
    try:
        import ledger
        error_type = ledger.PostError
    except Exception:
        error_type = ValueError
    raise error_type(message)


def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        _malformed_amount()

    text = dollars.strip()
    match = _AMOUNT_RE.fullmatch(text)
    if not match:
        _malformed_amount()

    sign, whole, frac1, frac2 = match.groups()
    frac = frac1 if frac1 is not None else frac2
    whole = whole or "0"
    frac = (frac or "").ljust(2, "0")

    try:
        cents = int(whole) * 100 + int(frac)
    except Exception:
        _malformed_amount()

    if sign == "-" and cents:
        cents = -cents

    return str(cents)


def post_amount(account: str, dollars: str, *, memo: str):
    import ledger
    return ledger.post(account, encode_amount(dollars), memo=memo)

