from decimal import Decimal, InvalidOperation
import json

_WIRE_KIND = None
_ORACLE_EXHAUSTED = False


def encode_amount(dollars: str) -> str:
    cents = _parse_cents(dollars)

    native = _try_native_encoder(dollars, cents)
    if native is not None:
        return native

    global _WIRE_KIND
    if _WIRE_KIND is not None:
        return _format_kind(_WIRE_KIND, cents)

    discovered = _try_ledger_oracle(cents)
    if discovered is not None:
        kind, value = discovered
        _WIRE_KIND = kind
        return value

    return str(cents)


def _parse_cents(dollars: str) -> int:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    try:
        amount = Decimal(s)
    except InvalidOperation as exc:
        raise ValueError("malformed amount") from exc

    if not amount.is_finite():
        raise ValueError("malformed amount")

    cents = amount * Decimal(100)
    if cents != cents.to_integral_value():
        raise ValueError("amount has more than two decimal places")

    return int(cents)


def _fixed(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    n = abs(cents)
    return f"{sign}{n // 100}.{n % 100:02d}"


def _base36(n: int) -> str:
    sign = "-" if n < 0 else ""
    n = abs(n)
    chars = "0123456789abcdefghijklmnopqrstuvwxyz"
    if n == 0:
        return "0"
    out = []
    while n:
        n, r = divmod(n, 36)
        out.append(chars[r])
    return sign + "".join(reversed(out))


def _format_kind(kind: str, cents: int) -> str:
    fixed = _fixed(cents)
    c = str(cents)
    b36 = _base36(cents)

    if kind == "cents":
        return c
    if kind == "fixed":
        return fixed
    if kind == "signed_cents":
        return f"{cents:+d}"
    if kind == "c_suffix":
        return f"{c}c"
    if kind == "cents_prefix":
        return f"cents:{c}"
    if kind == "amount_prefix":
        return f"amount:{c}"
    if kind == "money_prefix":
        return f"money:{c}"
    if kind == "v1_cents":
        return f"v1:{c}"
    if kind == "wire_cents":
        return f"wire:{c}"
    if kind == "usd_cents_colon":
        return f"USD:{c}"
    if kind == "usd_cents_space":
        return f"USD {c}"
    if kind == "usd_fixed_colon":
        return f"USD:{fixed}"
    if kind == "usd_fixed_space":
        return f"USD {fixed}"
    if kind == "fixed_usd_space":
        return f"{fixed} USD"
    if kind == "json_cents":
        return json.dumps({"cents": cents}, separators=(",", ":"))
    if kind == "json_amount":
        return json.dumps({"amount": fixed}, separators=(",", ":"))
    if kind == "json_usd_cents":
        return json.dumps({"currency": "USD", "cents": cents}, separators=(",", ":"))
    if kind == "json_usd_amount":
        return json.dumps({"currency": "USD", "amount": fixed}, separators=(",", ":"))
    if kind == "base36":
        return b36
    if kind == "base36_prefix":
        return f"b36:{b36}"

    return c


