        "json_usd_amount",
        "base36",
        "base36_prefix",
    )


def _try_native_encoder(dollars: str, cents: int):
    try:
        import ledger
    except Exception:
        return None

    names = (
        "encode_amount",
        "_encode_amount",
        "serialize_amount",
        "_serialize_amount",
        "amount_to_wire",
        "_amount_to_wire",
        "to_wire_amount",
        "_to_wire_amount",
