def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if s.startswith("-"):
        sign = "-"
        num = s[1:]
    else:
        sign = "+"
        num = s.lstrip("+")

    if "." in num:
        whole, frac = num.split(".")
        frac = (frac + "00")[:2]
    else:
        whole = num
        frac = "00"

    digits = whole.lstrip("0") + frac
    digits = digits.lstrip("0")
    if not digits:
        digits = "0"

    check = sum(int(d) for d in digits) % 10
    return f"{sign}{digits}#{check}"

