from decimal import Decimal, InvalidOperation
import base64
import json

_STYLE_INDEX = None


def _parse_cents(dollars: str) -> int:
    try:
        value = Decimal(str(dollars).strip())
    except (InvalidOperation, ValueError) as exc:
        raise ValueError("malformed dollar amount") from exc

    if not value.is_finite():
        raise ValueError("malformed dollar amount")

    cents = value * Decimal(100)
    integral = cents.to_integral_value()
    if cents != integral:
        raise ValueError("amount must have no more than two decimal places")

    return int(integral)


def _dollars(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents_abs = abs(cents)
    return f"{sign}{cents_abs // 100}.{cents_abs % 100:02d}"


def _base36(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    n = abs(cents)
    chars = "0123456789abcdefghijklmnopqrstuvwxyz"
    if n == 0:
        return "0"
    out = []
    while n:
        n, r = divmod(n, 36)
        out.append(chars[r])
    return sign + "".join(reversed(out))


def _b64_ascii(text: str) -> str:
    return base64.b64encode(text.encode("ascii")).decode("ascii")


def _candidate_formatters():
    return (
        lambda c: str(c),
        lambda c: _dollars(c),
        lambda c: f"v1:{c}",
        lambda c: f"amt:{c}",
        lambda c: f"amount:{c}",
        lambda c: f"cents:{c}",
        lambda c: f"USD:{c}",
        lambda c: f"USD {c}",
        lambda c: f"USD:{_dollars(c)}",
        lambda c: f"USD {_dollars(c)}",
        lambda c: f"${_dollars(c)}",
        lambda c: f"-${_dollars(abs(c))}" if c < 0 else f"${_dollars(c)}",
        lambda c: json.dumps({"cents": c}, separators=(",", ":")),
        lambda c: json.dumps({"amount": _dollars(c)}, separators=(",", ":")),
        lambda c: json.dumps({"currency": "USD", "cents": c}, separators=(",", ":")),
        lambda c: f"{'-' if c < 0 else ''}{abs(c):012d}",
        lambda c: _base36(c),
        lambda c: f"b36:{_base36(c)}",
        lambda c: _b64_ascii(str(c)),
        lambda c: f"base64:{_b64_ascii(str(c))}",
        lambda c: hex(c),
        lambda c: f"wire:{c}",
        lambda c: f"ledger:{c}",
    )


def _try_ledger_encoder(dollars: str, cents: int):
    try:
        import ledger
    except Exception:
        return None

    names = (
        "encode_amount",
        "_encode_amount",
        "serialize_amount",
        "_serialize_amount",
        "amount_to_wire",
        "_amount_to_wire",
        "to_wire_amount",
        "_to_wire_amount",
        "format_amount",
        "_format_amount",
    )

    for name in names:
        fn = getattr(ledger, name, None)
        if not callable(fn):
            continue
        for arg in (dollars, _dollars(cents), Decimal(cents) / Decimal(100), cents):
            try:
                result = fn(arg)
            except Exception:
                continue
            if isinstance(result, str):
                return result

    return None


def _strings_from_value(value):
    if value is None:
        return

    if isinstance(value, str):
        yield value
        return

    if isinstance(value, dict):
        iterable = value.keys()
    else:
        iterable = value

    try:
        iterator = iter(iterable)
    except TypeError:
        name = getattr(value, "name", None)
        if isinstance(name, str):
            yield name
        return

    for item in iterator:
        if isinstance(item, str):
            yield item
        else:
            name = getattr(item, "name", None)
            if isinstance(name, str):
                yield name


def _candidate_accounts(ledger):
    seen = set()

    attr_names = (
        "DEFAULT_ACCOUNT",
        "default_account",
        "_DEFAULT_ACCOUNT",
        "ACCOUNTS",
        "accounts",
        "_accounts",
        "VALID_ACCOUNTS",
        "valid_accounts",
        "_valid_accounts",
        "ACCOUNT_NAMES",
        "account_names",
        "_account_names",
    )

    for name in attr_names:
        if not hasattr(ledger, name):
            continue
        value = getattr(ledger, name)
        if callable(value):
            try:
                value = value()
            except TypeError:
                continue
            except Exception:
                continue
        for account in _strings_from_value(value) or ():
            if account not in seen:
                seen.add(account)
                yield account

    common = (
        "cash",
        "checking",
        "savings",
