from decimal import Decimal, InvalidOperation, ROUND_DOWN


def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = "+"
    if s[0] in "+-":
        if s[0] == "-":
            sign = "-"
        s = s[1:]

    if not s:
        raise ValueError("invalid amount")

    if s.startswith("$"):
        s = s[1:]

    if not s:
        raise ValueError("invalid amount")

    if s.count(".") > 1:
        raise ValueError("invalid amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if not whole.isdigit() or (frac and not frac.isdigit()):
        raise ValueError("invalid amount")

    if len(frac) > 2:
        raise ValueError("amount must have no more than two decimal places")

    frac = frac.ljust(2, "0")
    cents = int(whole) * 100 + int(frac or "0")

    if cents == 0:
        digits = "0"
    else:
        digits = str(cents)

    check = sum(int(ch) for ch in digits) % 10
    return f"{sign}{digits}#{check}"

