def encode_amount(dollars: str) -> str:
    match = re.fullmatch(r'(?P<sign>-?)(?P<whole>\d+)\.(?P<frac>\d{2})', dollars)
    if not match:
        raise ValueError(f'malformed amount: {dollars!r}')
    sign = -1 if match['sign'] else 1
    whole = int(match['whole'])
    frac = int(match['frac'])
    return str(sign * (whole * 100 + frac))

