def _post_error(message: str):
    try:
        import ledger
        exc = getattr(ledger, "PostError", ValueError)
    except Exception:
        exc = ValueError
    return exc(message)


def encode_amount(dollars: str) -> str:
    try:
        value = Decimal(dollars)
    except (InvalidOperation, TypeError):
        raise _post_error("malformed amount")

    cents_value = value * Decimal("100")
    if cents_value != cents_value.to_integral_value():
        raise _post_error("malformed amount")

    cents = int(cents_value.to_integral_value(rounding=ROUND_HALF_UP))
