    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = "+"
    if s[0] in "+-":
        sign = s[0]
        s = s[1:]

    if not s:
        raise ValueError("invalid amount")

    if s.count(".") > 1:
        raise ValueError("invalid amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if not whole.isdigit() or (frac and not frac.isdigit()):
        raise ValueError("invalid amount")

    if len(frac) > 2 and any(ch != "0" for ch in frac[2:]):
        raise ValueError("amount has sub-cent precision")

    frac = (frac + "00")[:2]
    digits = (whole + frac).lstrip("0") or "0"
    check = sum(ord(ch) - ord("0") for ch in digits) % 10

    return f"{sign}{digits}#{check}"

