import re

def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")
    if not re.fullmatch(r"-?\d+(?:\.\d{2})?", dollars):
        raise ValueError(f"malformed amount: {dollars!r}")
    negative = dollars.startswith("-")
    body = dollars[1:] if negative else dollars
    if "." in body:
        whole, cents = body.split(".")
    else:
        whole, cents = body, "00"
    combined = (whole + cents).lstrip("0")
    if not combined:
        combined = "0"
    return "-" + combined if negative and combined != "0" else combined

