def encode_amount(dollars: str) -> str:
    raw = dollars.lstrip('+')
    if raw.startswith('-'):
        sign = '-'
        num = raw[1:]
    else:
        sign = '+'
        num = raw

    if '.' in num:
        whole, frac = num.split('.', 1)
        if len(frac) >= 2:
            frac = frac[:2]
        elif len(frac) == 1:
            frac = frac + '0'
        else:
            frac = '00'
    else:
