        frac = '00'

    whole_int = int(whole) if whole else 0
    frac_int = int(frac)
    minor = whole_int * 100 + frac_int
    digits = str(minor)

    check = sum(int(ch) for ch in digits) % 10
    return f"{sign}{digits}#{check}"

