import re


_AMOUNT_RE = re.compile(r"^([+-]?)(?:(\d+)(?:\.(\d{1,2}))?|\.(\d{1,2}))$")


def _malformed(message: str):
    try:
        import ledger  # type: ignore

        raise ledger.PostError(message)
    except ImportError:
        raise ValueError(message)


def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        _malformed("amount must be a string")

    match = _AMOUNT_RE.fullmatch(dollars)
    if not match:
        _malformed("malformed amount")

    sign, whole, frac_a, frac_b = match.groups()
    whole = whole or "0"
    frac = frac_a if frac_a is not None else frac_b
    frac = (frac or "").ljust(2, "0")

    cents = int(whole) * 100 + int(frac)
    if cents == 0:
        return "0"

    return f"-{cents}" if sign == "-" else str(cents)

