from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def encode_amount(dollars: str) -> str:
    """
    Encode a dollar-denominated amount as the private wire amount string:
    signed integer cents, with no decimal point and no insignificant leading
    zeroes.
    """
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    text = dollars.strip()
    if not text:
        raise ValueError("empty amount")

    try:
        value = Decimal(text)
    except InvalidOperation as exc:
        raise ValueError("malformed amount") from exc

    cents_value = value * Decimal("100")
    if cents_value != cents_value.to_integral_value():
        raise ValueError("amount has more than two decimal places")

    cents = int(cents_value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    return str(cents)

