import re

_MONEY_RE = re.compile(r"^\s*([+-]?)(?:(\d+)(?:\.(\d{0,2}))?|\.(\d{1,2}))\s*$")


def encode_amount(dollars: str) -> str:
    match = _MONEY_RE.match(dollars)
    if not match:
        raise ValueError(f"malformed dollar amount: {dollars!r}")

    sign, whole, frac1, frac2 = match.groups()
    whole_cents = int(whole or "0") * 100
    frac = (frac1 if frac1 is not None else frac2 or "").ljust(2, "0")
    cents = whole_cents + int(frac or "0")

    if sign == "-" and cents:
        cents = -cents

    return str(cents)

