from decimal import Decimal, InvalidOperation

def encode_amount(dollars: str) -> str:
    try:
        value = Decimal(dollars)
    except InvalidOperation as exc:
        raise ValueError(f"invalid amount: {dollars!r}") from exc

    exponent = value.as_tuple().exponent
    if isinstance(exponent, int) and exponent < -2:
        raise ValueError(f"amount has too many decimal places: {dollars!r}")

    cents = value * 100
    if cents != cents.to_integral_value():
        raise ValueError(f"non-integral cents for amount: {dollars!r}")

    return str(int(cents.to_integral_value()))

