def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a str")

    sign = ""
    if dollars.startswith("-"):
        sign = "-"
        dollars = dollars[1:]
    elif dollars.startswith("+"):
        dollars = dollars[1:]

    if not dollars:
        raise ValueError("Invalid amount")

    if "." in dollars:
        if dollars.count(".") != 1:
            raise ValueError("Invalid amount")
        whole, frac = dollars.split(".")
        if len(frac) > 2:
            raise ValueError("Invalid amount")
        frac = (frac + "00")[:2]
    else:
        whole, frac = dollars, "00"

    whole = whole or "0"

    if not whole.isdigit() or not frac.isdigit():
        raise ValueError("Invalid amount")

    cents = whole.lstrip("0") + frac
    cents = cents.lstrip("0") or "0"

    if sign and cents != "0":
        cents = sign + cents

    return cents

