from decimal import Decimal, ROUND_HALF_EVEN

def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if s.startswith('-'):
        sign = '-'
        num = s[1:]
    else:
        sign = '+'
        num = s.lstrip('+')

    if not num:
        raise ValueError("Invalid amount")

    if '.' in num:
        whole, frac = num.split('.', 1)
        base = int(whole) if whole else 0
        if not frac:
            cents = base * 100
        elif len(frac) == 1:
            cents = base * 100 + int(frac) * 10
        elif len(frac) == 2:
            cents = base * 100 + int(frac)
        else:
            d = Decimal(num) * 100
            cents = int(d.to_integral_value(rounding=ROUND_HALF_EVEN))
    else:
        cents = int(num) * 100

    digits = str(abs(cents))
    check = sum(int(d) for d in digits) % 10
    return f"{sign}{digits}#{check}"

